"use client";
import React, { JSX, useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '../context/AuthContext';
import ErrorMessage from '../components/shared/ErrorMessage';
import { Eye, EyeOff } from 'lucide-react';
import Link from 'next/link';
import { GoogleLogin } from '@react-oauth/google';

export default function LoginPage(): JSX.Element {
  const router = useRouter();
  const { login, loginWithGoogle, loginWithFacebook } = useAuth();
  const [identifier, setIdentifier] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [identifierWarning, setIdentifierWarning] = useState<string | null>(null);

  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  // Validate email or phone
  const validateIdentifier = (value: string) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const phoneRegex = /^[\+]?[(]?[0-9]{1,4}[)]?[-\s\.]?[(]?[0-9]{1,4}[)]?[-\s\.]?[0-9]{1,9}$/;

    if (value && !emailRegex.test(value) && !phoneRegex.test(value)) {
      setIdentifierWarning('Please enter a valid email or phone number');
    } else {
      setIdentifierWarning(null);
    }
  };

  const handleIdentifierChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setIdentifier(value);
    validateIdentifier(value);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccessMessage(null);

    // Final validation before submit
    if (!identifier || !password) {
      setError('Please fill in all fields');
      return;
    }

    if (identifierWarning) {
      setError('Please fix the errors before submitting');
      return;
    }

    setLoading(true);
    try {
      const result = await login(identifier, password);
      if (result.success) {
        setSuccessMessage('Login successful! Redirecting...');
        // Delay redirect to show success message
        setTimeout(() => {
          router.push('/');
        }, 1000);
      } else {
        setError(result.error || 'Invalid credentials');
      }
    } catch (err: any) {
      setError(err?.message || 'Invalid credentials');
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleSuccess = async (credentialResponse: any) => {
    setLoading(true);
    setError(null);
    try {
      // credentialResponse.credential contains the JWT ID token
      const result = await loginWithGoogle(credentialResponse.credential, false);
      if (result.success) {
        setSuccessMessage('Login successful! Redirecting...');
        setTimeout(() => {
          router.push('/');
        }, 1000);
      } else {
        setError(result.error || 'Google login failed');
      }
    } catch (err: any) {
      console.error('Google login error:', err);
      setError(err?.message || 'Google login failed');
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleError = () => {
    console.error('Google Login Failed');
    setError('Google login failed');
  };

  const handleFacebookLogin = () => {
    // Initialize Facebook SDK and login
    if (typeof window !== 'undefined' && (window as any).FB) {
      (window as any).FB.login((response: any) => {
        if (response.authResponse) {
          setLoading(true);
          loginWithFacebook(response.authResponse.accessToken, response.authResponse.userID)
            .then((result) => {
              if (result.success) {
                setSuccessMessage('Login successful! Redirecting...');
                setTimeout(() => {
                  router.push('/');
                }, 1000);
              } else {
                setError(result.error || 'Facebook login failed');
              }
            })
            .catch((err) => {
              setError(err?.message || 'Facebook login failed');
            })
            .finally(() => {
              setLoading(false);
            });
        } else {
          setError('Facebook login cancelled');
        }
      }, { scope: 'public_profile,email' });
    } else {
      setError('Facebook SDK not loaded');
    }
  };

  // Load Facebook SDK
  useEffect(() => {
    if (typeof window !== 'undefined') {
      (window as any).fbAsyncInit = function () {
        (window as any).FB.init({
          appId: process.env.NEXT_PUBLIC_FACEBOOK_APP_ID,
          cookie: true,
          xfbml: true,
          version: 'v18.0'
        });
      };

      // Load the SDK asynchronously
      (function (d, s, id) {
        var js: any, fjs: any = d.getElementsByTagName(s)[0];
        if (d.getElementById(id)) return;
        js = d.createElement(s); js.id = id;
        js.src = "https://connect.facebook.net/en_US/sdk.js";
        fjs.parentNode.insertBefore(js, fjs);
      }(document, 'script', 'facebook-jssdk'));
    }
  }, []);

  return (
    <div className="flex justify-center items-center min-h-screen bg-gray-50">
      <form
        onSubmit={handleSubmit}
        className="flex flex-col gap-3 bg-white p-8 w-full max-w-md rounded-2xl shadow-md font-[system-ui]"
      >
        <h2 className="text-2xl font-semibold text-gray-800 mb-1 text-center">
          Welcome Back
        </h2>
        <p className="text-sm text-gray-600 text-center mb-4">
          Sign in to continue to Dosro Bazar
        </p>

        {/* Email or Phone Field */}
        <div className="flex flex-col">
          <label className="text-gray-800 font-semibold mb-1" htmlFor="identifier">
            Email or Phone Number
          </label>
          <div className={`flex items-center border rounded-lg h-12 px-3 transition ${identifierWarning ? 'border-amber-400 focus-within:border-amber-500' : 'border-gray-200 focus-within:border-blue-500'
            }`}>
            <input
              id="identifier"
              name="identifier"
              type="text"
              autoComplete="off"
              value={identifier}
              onChange={handleIdentifierChange}
              onBlur={() => validateIdentifier(identifier)}
              placeholder="Enter your email or phone"
              className="w-full border-none outline-none bg-transparent text-gray-700 placeholder-gray-400"
            />
          </div>
          {identifierWarning && (
            <div className="mt-2">
              <ErrorMessage variant="warning" message={identifierWarning} />
            </div>
          )}
        </div>

        {/* Password Field */}
        <div className="flex flex-col mt-3">
          <label className="text-gray-800 font-semibold mb-1" htmlFor="password">
            Password
          </label>
          <div className="flex items-center border border-gray-200 rounded-lg h-12 px-3 focus-within:border-blue-500 transition">
            <input
              id="password"
              name="password"
              type={showPassword ? 'text' : 'password'}
              autoComplete="off"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Enter your password"
              className="w-full border-none outline-none bg-transparent text-gray-700 placeholder-gray-400"
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="ml-2 text-gray-500 hover:text-gray-700 focus:outline-none"
            >
              {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
            </button>
          </div>
        </div>

        {/* Remember me + Forgot Password */}
        <div className="flex justify-between items-center mt-2 text-sm">
          <label className="flex items-center space-x-2">
            <input type="checkbox" className="accent-blue-500" />
            <span className="text-gray-700">Remember me</span>
          </label>
          <Link href="/forgotPassword" className="text-blue-600 cursor-pointer hover:underline">
            Forgot password?
          </Link>
        </div>

        {successMessage && <ErrorMessage variant="success" message={successMessage} />}
        {error && <ErrorMessage error={error} />}

        {/* Submit */}
        <button
          disabled={loading}
          type="submit"
          className="w-full mt-4 bg-gray-900 text-white py-3 rounded-lg font-medium hover:bg-gray-800 transition disabled:opacity-60"
        >
          {loading ? 'Signing in...' : 'Sign In'}
        </button>

        {/* Sign Up */}
        <p className="text-center text-gray-700 text-sm mt-2">
          Don't have an account?{' '}
          <Link href='/signUp' className="text-blue-600 font-medium cursor-pointer hover:underline">Sign Up</Link>
        </p>

        <p className="text-center text-gray-500 text-sm my-2">Or With</p>

        {/* Google Login Button */}
        <div className="flex justify-center">
          <GoogleLogin
            onSuccess={handleGoogleSuccess}
            onError={handleGoogleError}
            useOneTap
            theme="outline"
            size="large"
            text="continue_with"
            shape="rectangular"
            width="384"
          />
        </div>

        {/* Facebook Login Button */}
        <button
          type="button"
          onClick={handleFacebookLogin}
          className="flex items-center justify-center gap-2 border border-gray-200 rounded-lg py-3 hover:border-blue-500 transition"
        >
          <svg className="w-5 h-5" fill="#1877F2" viewBox="0 0 24 24">
            <path d="M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z" />
          </svg>
          Continue with Facebook
        </button>
      </form>
    </div>
  );
}
